sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Roboto:wght@500&display=swap');
/* --- Variáveis --- */
$ranking-color-initial: #a7b9e8; // Cor inicial do gráfico (azul claro)
$ranking-color-hover: #4b77bf;     // Cor ao passar o mouse (azul escuro)
$ranking-title-color: #021770;     // Cor do título


/* --- Estilos do Título --- */

// Remove o background, border e padding padrão do painel

.panel{
	   border: none !important;
}

/* --- Estilos do Título --- */

// Aplica o espaçamento superior e lateral ao container do título
.panel-heading {
    background-color: transparent;
    border: none;
    padding-top: 15px;    
    padding-left: 20px;   
    padding-right: 0;     
    //margin-bottom: 15px;
}

// Estilos específicos para o Título (h3.panel-title)
.panel-title {
    font-family: 'Roboto', sans-serif;
    font-weight: 500;
    font-size: 24px;
    line-height: 100%;
    color: $ranking-title-color;

    /* Remove text-align: center se tiver sido adicionado */
    text-align: left; 

    /* Remove qualquer margem extra se não for necessária */
    margin: 0; 
}

/* --- Estilos do Ranking --- */

.ranking-bar-container {
    display: flex;
    align-items: center; // Alinha todos os itens (label, barra, valor) verticalmente
    margin-bottom: 5px;
    height: 25px;
}

.ranking-label {
    font-family: 'Roboto', sans-serif;
    width: 150px;
    font-weight: bold;
    font-size: 14px;
    text-align: right;
    padding-right: 10px;
    /* 🎯 NOVA COR para o Label */
    color: #1d2f80; 
}

.ranking-bar-wrapper {
  	overflow: visible;
    flex-grow: 1; // Ocupa o espaço restante
    height: 100%;
    /* Deixa espaço para o label (150px) e para a porcentagem (cerca de 50px) */
    max-width: calc(100% - 150px - 50px);
    margin-right: 10px; // Espaçamento entre a barra e a porcentagem
}

.ranking-bar {
    height: 80%;
    background-color: $ranking-color-initial;
    border-radius: 2px;
    box-sizing: border-box;
    min-width: 5px;

    /* Transição suave para cor E escala (transform) */
    transition: background-color 0.3s ease, transform 0.3s ease;
    transform: scale(1);
    transform-origin: left; // Faz o crescimento no hover ser da esquerda para a direita
}

/* Efeito Hover: muda a cor do background e aumenta a escala */
.ranking-bar:hover {
    background-color: $ranking-color-hover;
    cursor: pointer;
    transform: scale(1.01); 
}

/* Estilo para o valor da porcentagem (agora fora da barra) */
.ranking-value {
    font-family: 'Roboto', sans-serif;
    /* 🎯 NOVA COR para o Ranking Value */
    color: #1d2f80; 
    font-weight: bold;
    font-size: 14px; 
    width: 40px; // Largura fixa para manter o alinhamento
    text-align: left;
}

// Estilo específico para o item com 100% (se houver necessidade de destaque)
.ranking-bar[ng-style*="'width': 100"] {
    background-color: #3867c2;

    &:hover {
        background-color: $ranking-color-hover; 
    }
}


/*----------------------------*/
/* --- Estilos Completos para o Card de Informações --- */

/* 1. Container Principal do Card */
.ranking-info-card {
    border: 1px solid #C8C5C5; 
    border-radius: 4px;
    margin-bottom: 20px; 
    border-top: none; 
}

/* 2. Cabeçalho do Card (Contém o Título) */
.ranking-info-heading {
    /* Cor de fundo solicitada */
    background-color: #F1F4FB; 

    /* Borda superior solicitada */
    border-top: 0.5px solid #C8C5C5; 

    border-bottom: none; 
    padding: 10px 15px;
}

/* 3. Título (h3) dentro do Cabeçalho */
.ranking-info-title {
    /* Estilos do Título solicitados */
    font-family: 'Roboto', sans-serif;
    font-weight: 600; /* SemiBold */
    font-size: 16px;
    color: #021770; 

    /* Propriedades de espaçamento */
    line-height: 100%;
    letter-spacing: 0%;
    vertical-align: bottom;

    margin: 0; /* Essencial para remover margens padrão do H3 */
    padding: 0; 
}

/* 4. Corpo do Card */
.ranking-info-body {
    padding: 15px;
    border-top: 1px solid #C8C5C5; /* Separador entre heading e body */
}

/* 5. Parágrafos dentro do corpo */
.ranking-info-body p {
    margin-bottom: 5px; 
    line-height: 100%; 
}

/* 6. Rótulos (Descrição, Fonte, Atualização) - Estilo SemiBold (600) */
.ranking-info-label {
    font-family: 'Roboto', sans-serif;
    font-weight: 600; /* SemiBold */
    font-size: 14px;
    color: #021770; 

    line-height: 100%;
    letter-spacing: 0%;
    vertical-align: bottom; 
    margin-right: 5px;
}

/* 7. Conteúdo (Valores: Descrição, Fonte, Atualização) - Estilo Light (300) */
.ranking-info-content {
    font-family: 'Roboto', sans-serif;
    font-weight: 100; /* Light */
    font-size: 12px;
    color: #021770; 

    line-height: 100%;
    letter-spacing: 0%;
    vertical-align: bottom; 

    font-style: normal;
}

sp_widget.script:
(function() {

    data.rankingData = []; // Array para armazenar os dados do gráfico

    // 1. Filtro para o tipo de ranking específico
    var rankingTypeSysId = gs.getProperty('x_sded9_portal_t_0.regra_de_ouro_id') ||'b0e84d38fb857210f6d5f9d38eefdc60';



    var grTipo = new GlideRecord('x_sded9_portal_t_0_tipos_de_ranking_area'); 
    if (grTipo.get(rankingTypeSysId)) {
        data.descricao = grTipo.u_descricao.toString();
        data.fonte = grTipo.u_fonte.getDisplayValue();
        data.atualizacao = grTipo.u_atualizacao.toString();
    } else {
        // Fallback caso o registro não seja encontrado
        data.descricao = 'Descrição não disponível.';
        data.fonte = 'Fonte não disponível.';
        data.atualizacao = 'Atualização não disponível.';
    }
    // =========================================================


    var gr = new GlideRecord('x_sded9_portal_t_0_dados_do_ranking');
    gr.addQuery('u_tipo_de_ranking', rankingTypeSysId);



    gr.query();

    while (gr.next()) {

         var estadoNome = gr.u_estado.getDisplayValue();
        var posicaoStr = gr.u_posicao.toString();
        var posicaoNum = parseInt(posicaoStr.replace(/\D/g, ''), 10);
        var porcentagemStr = gr.u_porcentagem.toString(); 
        var cleanedStr = porcentagemStr.replace(/,/g, '.'); 
        var porcentagemParaBarra = parseFloat(cleanedStr); 

        if (isNaN(porcentagemParaBarra)) {
             porcentagemParaBarra = 0;
        }

        data.rankingData.push({
            nome: estadoNome,
            posicao_str: posicaoStr, 
            posicao_num: posicaoNum, 
            porcentagem_num: porcentagemParaBarra
        });
    }

    data.rankingData.sort(function(a, b) {
        return b.posicao_num - a.posicao_num; 
    });

})();
